fragment:
precision highp float;
uniform sampler2D uSw, uIc, uRj;
uniform float uProj;
uniform float uIcon, uStay, uRefund, uOnAlly;
uniform vec3 uFrom;
const vec3 GOLD = vec3(1., .78, .3);
uniform vec2 uRes; uniform float uT, uS, uTr, uI, uL, uPow, uHeavy, uSky, uSeed, uSize, uPushK, uFrost, uCrawl, uTrap, uSet, uGhostC, uGhostD;
uniform int uEl, uShape, uFx, uStat, uClass, uStart, uMove;
uniform vec3 uP, uV, uAim, uCst, uTgt, uDum, uDum2, uC1, uC2, uC3, uX1, uX2, uCam, uLook, uPa, uPb;
const float F = 1.9; const float PI = 3.14159265; const float TAU = 6.2831853;
vec3 ro, fw, rt, up; vec2 uv;

const bool aresGame = true;
uniform bool aresComposite;
uniform sampler2D aresScene, aresActors, aresCells;
uniform sampler2D aresOriginal;
uniform mat4 aresProjection, aresInverseProjection, aresLocalToWorld;
uniform vec4 aresBoard;
uniform vec2 aresBoardSize;
uniform float aresVerticalScale;
uniform vec3 aresSpots[7];
uniform int aresSpotCount;
vec2 aresPixel() { return gl_FragCoord.xy / uRes; }
vec3 aresBackground() {
  vec3 finalColor = texture2D(aresScene, aresPixel()).rgb;
  float vignette = max(.05, 1. - .35 * dot(uv, uv));
  vec3 linearColor = pow(finalColor, vec3(1. / .9)) / vignette;
  return linearColor / max(vec3(.001), 1. - linearColor * .22);
}
vec2 aresBoardPoint(vec2 g) {
  vec3 world = (aresLocalToWorld * vec4(g.x, 0., g.y, 1.)).xyz;
  return (world.xz - aresBoard.xy) / aresBoard.z;
}
vec4 aresCell(vec2 g) {
  vec2 index = floor(aresBoardPoint(g));
  if (any(lessThan(index, vec2(0.))) || any(greaterThanEqual(index, aresBoardSize))) return vec4(0.);
  return texture2D(aresCells, (index + .5) / aresBoardSize);
}
vec3 aresOrigin() {
  vec4 nearPoint = aresInverseProjection * vec4(aresPixel() * 2. - 1., 0., 1.);
  return nearPoint.xyz / nearPoint.w;
}
vec3 aresRay() {
  if (!aresGame) return normalize(fw * F + rt * uv.x + up * uv.y);
  vec4 farPoint = aresInverseProjection * vec4(aresPixel() * 2. - 1., 1., 1.);
  return normalize(farPoint.xyz / farPoint.w - ro);
}
// Separate the authored change from its background so only the effect is upsampled.
// The canvas compositor blends display-space colors; an unchanged pixel has zero opacity.
vec4 aresOverlay(vec3 color) {
  vec3 background = texture2D(aresOriginal, aresPixel()).rgb;
  vec3 difference = clamp(color, 0., 1.) - background;
  vec3 opacity = max(difference / max(vec3(.001), 1. - background), -difference / max(vec3(.001), background));
  float alpha = clamp(max(opacity.r, max(opacity.g, opacity.b)), 0., 1.);
  return alpha < .001 ? vec4(0.) : vec4(background + difference / alpha, alpha);
}


float h1(float n){ return fract(sin(n * 127.1) * 43758.5453); }
float h2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float ns(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3. - 2. * f);
  return mix(mix(h2(i), h2(i + vec2(1, 0)), f.x), mix(h2(i + vec2(0, 1)), h2(i + vec2(1, 1)), f.x), f.y); }
float fbm(vec2 p){ float a = .5, s = 0.; for (int i = 0; i < 4; i++) { s += a * ns(p); p = p * 2.03 + 7.1; a *= .5; } return s; }
float sat(float x){ return clamp(x, 0., 1.); }
float sq(float x){ return x * x; }
float eo(float x){ x = 1. - sat(x); return 1. - x * x * x; }
float pop(float x){ return eo(x) * (1. + .3 * exp(-max(x, 0.) * 2.5) * sin(max(x, 0.) * 9.)); }
float ln(float d, float w){ return 1. - smoothstep(0., w, abs(d)); }
float win(float t, float a, float b, float f){ return smoothstep(a, a + .08, t) * (1. - smoothstep(b - f, b, t)); }
vec3 prj(vec3 P){
      if (aresGame) { vec4 p = aresProjection * vec4(P, 1.); float w = max(p.w, .001);
        return vec3(p.xy / w * vec2(uRes.x / uRes.y, 1.) * .5, w * F / aresVerticalScale); }
      vec3 d = P - ro; float z = max(dot(d, fw), .05); return vec3(vec2(dot(d, rt), dot(d, up)) * F / z, z);
    }
vec2 bb(vec3 P){ vec3 s = prj(P); return (uv - s.xy) * s.z / F; }
float pt(vec3 P, float k){ vec3 s = prj(P); return exp(-length(uv - s.xy) * s.z / F * k); }
vec2 rot(vec2 p, float a){ float c = cos(a), s = sin(a); return vec2(c * p.x - s * p.y, s * p.x + c * p.y); }
vec3 ramp(float d){ return uC3 * smoothstep(0., .3, d) * .8 + uC2 * smoothstep(.12, .6, d) + uC1 * smoothstep(.45, .95, d) + vec3(1.) * smoothstep(.9, 1.6, d); }
float cube(vec3 P, float s, float a){ vec2 q = rot(bb(P), a); return step(max(abs(q.x), abs(q.y)), s); }

// flat cartoon bands with a dark rim, painted opaque
void paint(inout vec3 col, float d, vec3 a, vec3 b, vec3 c){
  vec3 k = c * .45; k = mix(k, c * 1.25, smoothstep(.1, .12, d)); k = mix(k, b, smoothstep(.3, .32, d));
  k = mix(k, a, smoothstep(.58, .6, d)); k = mix(k, vec3(1., 1., .94), smoothstep(.92, .94, d));
  col = mix(col, k, smoothstep(.03, .05, d));
}
// shadow: violet rim, black inside
void shade(inout vec3 col, float d){
  col = mix(col, uC2, smoothstep(.03, .05, d)); col = mix(col, uC3 * .7, smoothstep(.13, .15, d)); col = mix(col, vec3(.025, 0., .05), smoothstep(.3, .32, d));
}
float fire_d(vec2 q, float w, float h, float sd){
  if (h < .03) return 0.;
  float y = q.y / h; if (y < -.2 || y > 1.3 || abs(q.x) > w * 3.) return 0.;
  vec2 u = vec2(q.x * 2., q.y * 1.3 - uT * 3.2) + sd * 7.;
  float n1 = fbm(u), n2 = ns(u * 1.6 + vec2(n1 * 2., -uT * 1.5));
  float x = (q.x + (n1 - .5) * w * 1.9 * sat(y)) / (w * (1. - .6 * sat(y)));
  float dn = exp(-x * x * 1.5) * (1. - smoothstep(.15, 1.15, y)) * smoothstep(-.18, .04, y);
  return max(dn * (.55 + 1.1 * n2) - .14 * sat(y), 0.) * 1.35;
}
void tfire(inout vec3 col, vec2 q, float w, float h, float sd){ paint(col, fire_d(q, w, h, sd), uC1, uC2, uC3); }
float ball_d(vec2 q, float R, float sd){
  float r = length(q) / max(R, .01); if (r > 1.5) return 0.;
  return max((1. - r * r) * (.55 + 1.1 * fbm(q * 1.5 + vec2(sd, -uT * 1.6))), 0.) * 1.3;
}

float glyphs(float a, float r, float R, float hw, float n, float sd){
  float y = (r - R) / hw; if (abs(y) > 1.) return 0.;
  float ai = a * n / TAU, id = floor(ai), f = (fract(ai) - .5) * 2.;
  float h = h1(id + sd * 17.), s = 0.;
  s += ln(f - (h - .5) * .9, .2) * step(abs(y), .85) * step(.25, h);
  s += ln(y - (fract(h * 7.) - .5) * 1.4, .3) * step(abs(f), .62) * step(.35, fract(h * 3.));
  s += ln(y + f * (h > .5 ? 1. : -1.), .3) * step(abs(f), .6) * step(.55, fract(h * 11.));
  return min(s, 1.);
}
// a rune circle whose layers turn on their own and whose inner figure changes with the seed
float emblem(vec2 p, float sd, float k){
  float r = length(p); if (r > 1.3 || k <= 0.) return 0.;
  float a = atan(p.y, p.x), t = uT, st = floor(h1(sd * 1.7) * 4.), n = 3. + floor(h1(sd * 2.3) * 4.);
  float k1 = sat(k * 2.), k2 = sat(k * 2. - .5), k3 = sat(k * 2. - 1.);
  float s = ln(r - 1., .026) * step(fract((a + t * .3) / TAU + .5), k1) + exp(-abs(r - 1.) * 14.) * .2 * k1;
  s += ln(r - .84, .016) * step(.35, fract((a - t * .9) * n * 2. / TAU)) * k2;
  s += glyphs(a + t * .35, r, .92, .06, 16. + n, sd) * .9 * k2;
  float br = .62 + .05 * sin(t * 2. + sd);
  if (st < 1.) {
    float seg = TAU / n, inr = br * cos(seg * .5);
    float a1 = mod(a - t * .6, seg) - seg * .5, a2 = mod(a + t * .6 + seg * .5, seg) - seg * .5;
    s += (ln(r * cos(a1) - inr, .018) + ln(r * cos(a2) - inr, .018)) * step(r, br + .02) * k3;
  } else if (st < 2.) {
    s += (ln(r - (.45 + .17 * cos(n * (a + t * .5))), .02) + ln(r - (.3 + .1 * cos(n * (a - t * .8))), .016)) * k3;
  } else if (st < 3.) {
    vec2 q = rot(p, t * .7), q2 = rot(p, -t * .7);
    s += (ln(max(abs(q.x), abs(q.y)) - br * .7, .018) + ln(abs(q2.x) + abs(q2.y) - br, .018)) * k3;
    for (int i = 0; i < 4; i++) { float ao = float(i) * 1.5708 - t * 1.3; s += ln(length(p - vec2(cos(ao), sin(ao)) * .84) - .07, .02) * k3; }
  } else {
    s += ln(sin(n * (a + t * .4)) * r, .03) * step(.2, r) * step(r, br) * k3;
    for (int i = 0; i < 3; i++) { float ao = float(i) * 2.094 + t; vec2 c = vec2(cos(ao), sin(ao)) * .5; s += ln(length(p - c) - .16, .018) * step(.14, length(p - c * 1.25)) * k3; }
  }
  s += ln(r - .14 - .03 * sin(t * 5.), .014) * k3 + (1. - smoothstep(0., .14, r)) * .6 * k3;
  s += ln(r - fract(t * .5 + sd) * 1.05, .03) * (1. - fract(t * .5 + sd)) * .5 * k2;
  return s;
}
vec3 inks(float s){ return (uC2 + uC1 * s * .5) * s; }

float box(vec3 o, vec3 d, vec3 c, vec3 b, out vec3 n){
  vec3 m = 1. / d, k = abs(m) * b, q = m * (o - c), t1 = -q - k, t2 = -q + k;
  float tn = max(max(t1.x, t1.y), t1.z), tf = min(min(t2.x, t2.y), t2.z);
  if (tn > tf || tf < 0.) return 1e9;
  n = -sign(d) * step(t1.yzx, t1.xyz) * step(t1.zxy, t1.xyz);
  return tn;
}
// a spike built from stacked blocks: lit top faces, light and dark sides, dark outline
void vspike(inout vec3 col, vec3 P, float h, float w){
  if (h < .05) return;
  vec2 q = bb(P); float y = q.y / h; if (y < 0. || y > 1.) return;
  float steps = 5., lvl = floor(y * steps), wl = w * (1. - lvl / steps) + .03, fy = fract(y * steps);
  if (abs(q.x) > wl) return;
  vec3 c = mix(uC3 * 1.1 + uC2 * .2, uC2 * .95 + uC1 * .1, step(q.x, -wl * .1));
  c = mix(c, uC1, step(.7, fy));
  c = mix(c, uC3 * .3, max(step(wl - .035, abs(q.x)), step(fy, .08)));
  col = c;
}

// a blade of shadow: black body, a pulsing vein of light, violet fire on the edge, and it dissolves into wisps
void sblade(inout vec3 col, vec2 q, float len, float w, float ang, float hook, float life, float ghost){
  if (len < .05) return;
  vec2 p = rot(q, ang); float u = p.y / len; if (u < -.05 || u > 1.08) return;
  float lat = p.x - hook * u * u * len;
  float wid = w * pow(max(1. - u, 0.), .65) * smoothstep(-.05, .12, u);
  if (abs(lat) > wid * 2.6 + .08) return;
  float n = fbm(vec2(p.x * 5., p.y * 3. - uT * 2.5) + ang * 7.);
  float e = 1. - abs(lat) / max(wid, .001), keep = smoothstep(life * 1.3 - .3, life * 1.3 - .2, n);
  float inside = smoothstep(0., .08, e) * keep;
  if (ghost > .5) { col += uC2 * inside * .2; return; }
  col += uC2 * smoothstep(-1.5, 0., e) * step(e, 0.) * smoothstep(.42, .8, n) * keep * .9;
  col = mix(col, vec3(.02, 0., .05), inside * .96);
  col += uC2 * (1. - smoothstep(0., .22, abs(e))) * keep * .9;
  col += uC1 * ln(lat + sin(u * 9. - uT * 6.) * wid * .18, .022) * inside * (.45 + .55 * sin(u * 12. - uT * 10.));
}
// a fan of blades rising from one cell, with a larger, later ghost behind it
void sfan(inout vec3 col, vec3 S, float tj, float size, float count){
  vec2 q = bb(S) + vec2(0., .05);
  float life = smoothstep(1.5, 2.9, tj);
  for (int j = 0; j < 5; j++) {
    float fj = float(j), k = fj - 2.; if (abs(k) > count) continue;
    float ang = k * .44 + sin(uT * 1.6 + fj) * .07, lenj = (1.7 + .6 * h1(fj + S.x)) * size * (1. - .12 * abs(k));
    sblade(col, q / 1.22, lenj * pop((tj - .1 - .03 * fj) / .2), .2 * size, ang, k * .16, life, 1.);
    sblade(col, q, lenj * pop((tj - .03 * fj) / .18), .2 * size, ang, k * .16, life, 0.);
  }
}

// a sword cut: a bright edge that sweeps round, with light streaming off its inner side
void slash(inout vec3 col, vec2 q, float R, float a0, float sweep, float tk, vec3 ca, vec3 cb){
  if (tk <= 0. || tk >= 1.) return;
  float r = length(q) / R; if (r > 1.25 || r < .25) return;
  float a = mod(atan(q.y, q.x) - a0 + PI, TAU) - PI, sg = sign(sweep), s = a * sg / abs(sweep);
  if (sg < 0. && a > 0.) s = (a - TAU) * sg / abs(sweep);
  if (sg > 0. && a < 0.) s = (a + TAU) * sg / abs(sweep);
  float head = eo(tk * 1.8), tail = eo((tk - .35) * 1.6);
  if (s < tail || s > head) return;
  float k = (s - tail) / max(head - tail, .001), th = .3 * sqrt(sin(PI * k)) * (.5 + .5 * k), d = r - 1.;
  float n = fbm(vec2(s * 9. - uT * 4., r * 7.));
  float body = smoothstep(-th, -th * .15, d) * step(d, 0.) * (.35 + 1.1 * n);
  col += cb * body * (1. - tk * .5) + ca * (ln(d, .03) * 1.6 + smoothstep(.55, .9, n) * body) + vec3(1.) * ln(d, .012) * k;
  col += ca * smoothstep(.6, .95, fbm(vec2(s * 14., r * 12. + uT * 3.))) * step(0., d) * step(d, .16) * k * .7;
}
// the game's own sword art. p.x runs across the blade, p.y from pommel (0) to tip (1); the icons are drawn on the diagonal
vec4 swtex(vec2 p, float id){
  vec2 uv = .5 + (vec2(p.y - .5) + vec2(p.x, -p.x)) * .76;
  if (uv.x < .01 || uv.x > .99 || uv.y < .01 || uv.y > .99) return vec4(0.);
  return texture2D(uSw, vec2((uv.x + id) / 3., uv.y));
}
float sword_id(){ return uEl == 0 ? 0. : uEl == 2 ? 2. : 1.; }
// that sword as a spirit: it shimmers, wears a soft halo, light runs down it, and it frays into wisps as life goes to 1.
// Tip at the origin, hilt above
void ssword(inout vec3 col, vec2 q, float len, float life, vec3 ca, vec3 cb){
  if (len < .1) return;
  vec2 p = vec2(q.x / len * 1.45, 1. - q.y / len);
  if (abs(p.x) > .55 || p.y < -.12 || p.y > 1.12) return;
  float id = sword_id(), n = fbm(vec2(q.x * 5., q.y * 3. - uT * 2.));
  vec2 pw = p + vec2((n - .5) * .05 / len, 0.);
  vec4 t = swtex(pw, id);
  float halo = 0., wide = 0.;
  for (int i = 0; i < 8; i++) { float a = float(i) * .785; vec2 o = vec2(cos(a), sin(a)); halo += swtex(pw + o * .045 / len, id).a; wide += swtex(pw + o * .13 / len, id).a; }
  halo /= 8.; wide /= 8.;
  float keep = smoothstep(life * 1.3 - .3, life * 1.3 - .2, n), a = t.a * keep;
  vec3 body = mix(t.rgb, ca, .3) * (1. + .7 * smoothstep(.5, .9, fbm(vec2(p.x * 9., p.y * 6. - uT * 3.))));
  col += cb * wide * (.35 + .5 * smoothstep(.4, .8, n)) * keep * (1. - t.a);
  col += ca * max(halo - t.a, 0.) * 1.5 * keep + ca * halo * (1. - keep) * smoothstep(.3, .7, n) * .7;
  col = mix(col, body, a * .82);
  col += ca * a * ln(fract(p.y * 3. - uT * 1.2) - .5, .07) * .6;
}

// a clock face of light. The minute hand drags two fading copies of itself behind it
float dial(vec2 p, float ha, float ma, float k){
  float r = length(p); if (r > 1.25 || k <= 0.) return 0.;
  float a = atan(p.x, p.y);
  float s = ln(r - 1., .025) * step(fract(a / TAU + .5), k * 1.2) + ln(r - .9, .012) * k + exp(-abs(r - 1.) * 12.) * .2 * k;
  float major = step(abs(fract(a * 4. / TAU + .5) - .5), .04);
  s += step(abs(fract(a * 12. / TAU + .5) - .5), .035) * step(.78 - .08 * major, r) * step(r, .9) * k;
  s += glyphs(a, r, .66, .07, 12., 3.) * .7 * k;
  s += ln(r - (.42 + .03 * step(.5, fract(a * 9. / TAU + uT * .3))), .014) * .6 * k;
  vec2 hp = rot(p, ha); s += step(abs(hp.x), .035 * (1. - hp.y / .5)) * step(0., hp.y) * step(hp.y, .5) * k;
  for (int j = 0; j < 3; j++) { vec2 mp = rot(p, ma - float(j) * .16); s += step(abs(mp.x), .02 * (1. - mp.y / .82) + .004) * step(-.1, mp.y) * step(mp.y, .82) * k * (1. - float(j) * .38); }
  s += ln(r - .05, .02) * k + (1. - smoothstep(0., .05, r)) * k;
  return s * (.85 + .15 * sin(uT * 7. + r * 9.));
}
// the Rojin's things, from the game's own art: 0 coin · 1 pickaxe · 2 nugget · 3 diamond · 4 amber · 5 jade · 6 key · 7 bag
vec4 rjtex(vec2 p, float id){
  vec2 uv = p + .5; if (uv.x < .02 || uv.x > .98 || uv.y < .02 || uv.y > .98) return vec4(0.);
  return texture2D(uRj, vec2((uv.x + mod(id, 4.)) / 4., (uv.y + 1. - floor(id / 4.)) / 2.));
}
// one of them, turned, flipped edge-on like a spinning coin, gilded, with a sheen that slides across it
void sprite(inout vec3 col, vec2 q, float size, float ang, float flip, float id, float gild, float glow){
  if (size < .02) return;
  col += GOLD * exp(-length(q) / size * 3.5) * glow * .45;
  vec2 p = rot(q, ang) / size; p.x /= max(abs(flip), .14);
  if (abs(p.x) > .5 || abs(p.y) > .5) return;
  vec4 t = rjtex(p, id);
  float l = dot(t.rgb, vec3(.3, .6, .1));
  vec3 c = mix(t.rgb, vec3(1., .78, .22) * (l * 1.7 + .12) + vec3(1., .95, .7) * smoothstep(.5, .8, l), gild);
  col = mix(col, c, t.a);
  col += vec3(1., .92, .6) * t.a * glow * smoothstep(.75, 1., sin(p.x * 5. + p.y * 5. + uT * 5.)) * .6;
}
void glint(inout vec3 col, vec2 q, float k){ col += vec3(1., .95, .75) * (exp(-length(q) * 30.) + exp(-abs(q.y) * 70.) * exp(-abs(q.x) * 9.) + exp(-abs(q.x) * 70.) * exp(-abs(q.y) * 9.)) * k; }
float sd_seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p - a, ba = b - a; return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0., 1.)); }
// the spell's own illustration, shown as a vision: round, with an edge eaten by mist, a living rim, and wisps coming off it
vec4 ictex(vec2 p, float id){
  vec2 uv = p + .5; if (uv.x < .02 || uv.x > .98 || uv.y < .02 || uv.y > .98) return vec4(0.);
  return texture2D(uIc, vec2((uv.x + mod(id, 5.)) / 5., (uv.y + 3. - floor(id / 5.)) / 4.));
}
void vision(inout vec3 col, vec2 q, float R, float life, float id){
  if (R < .03) return;
  vec2 p = q / (R * 2.); float r = length(p) * 2.; if (r > 1.6) return;
  float n = fbm(q * 3. + vec2(0., -uT * 1.5)), n2 = fbm(q * 6. + uT);
  vec4 t = ictex((p + (vec2(n, n2) - .5) * .05) * 1.06, id);
  float keep = smoothstep(life * 1.3 - .3, life * 1.3 - .2, n);
  float a = t.a * (1. - smoothstep(.6, 1., r + (n - .5) * .55)) * keep;
  col += uC2 * (1. - smoothstep(.5, 1.5, r)) * (.2 + .5 * n) * keep;
  col = mix(col, t.rgb * (1.1 + .5 * smoothstep(.5, .9, n2)), a * .92);
  col += t.rgb * a * .35;
  col += uC1 * ln(r - 1. - .07 * sin(atan(p.y, p.x) * 6. + uT * 3.), .07) * keep * .8;
  col += uC2 * smoothstep(.55, .9, fbm(vec2(q.x * 4., q.y * 2. - uT * 2.))) * (1. - smoothstep(.8, 1.6, r)) * step(.7, r) * keep * .6;
}
// the grimoire: two cream pages in a V, lines of runes that light up, a page turning, light in the gutter
void book(inout vec3 col, vec2 q, float open, float glow){
  float ax = abs(q.x), w = .34 * open + .03, h = .23, yy = q.y - ax * .32 + .05;
  if (ax > w + .08 || abs(yy) > h + .12) return;
  col = mix(col, vec3(.3, .1, .26), step(ax, w + .035) * step(abs(yy + .025), h + .035));
  float page = step(ax, w) * step(abs(yy), h);
