// which cells the spell hits, relative to the target cell
uniform sampler2D uPr; uniform float uSwap;
// painted props for the six later classes: 0 staff · 1 card · 2 dice · 3 clover · 4 flask · 5 doll · 6 flower
void prop(inout vec3 col, vec2 q, float size, float ang, float flip, float id, float glow){
  if (size < .02) return;
