  col = mix(col, t.rgb + uC1 * glow * .1, t.a);
  col += uC1 * t.a * glow * smoothstep(.8, 1., sin(p.x * 5. + p.y * 5. + uT * 4.)) * .45;
}
// a faceted ward, like stained glass. k assembles it pane by pane, crack breaks it
void ward(inout vec3 col, vec2 q, float R, float k, float crack, vec3 ca, vec3 cb){
  if (k <= 0. || R < .03 || crack >= 1.) return;
  vec2 p = q / R; p.y *= .82; float r = length(p); if (r > 1.2) return;
  float seg = TAU / 7., a = atan(p.y, p.x) + .2, fa = floor(a / seg + .5), la = a - fa * seg;
  float rr = r * cos(la) / cos(seg * .5), ring = floor(rr * 3.), id = h1(fa * 3.1 + ring * 7.7 + 2.);
  float on = step(id, k * 1.2) * step(rr, 1.) * step(crack * 1.1, h1(fa + ring * 3. + 5.) + .1);
  float lines = ln(abs(la) - seg * .5, .05 / max(r, .25)) + ln(fract(rr * 3. + .5) - .5, .07) * step(rr, .95) + ln(rr - 1., .05) * 1.5;
  col += (cb * (.1 + .22 * id) * (.7 + .3 * sin(uT * 2. + id * 9.)) + ca * lines * .55 + ca * smoothstep(.75, 1., sin(p.x * 4. + p.y * 4. + uT * 2.5 + id * 6.)) * .12) * on;
}
// a line of written marks. p.x runs 0..1 along the line, p.y -1..1 across it
float script(vec2 p, float n, float sd){
  if (p.x < 0. || p.x > 1. || abs(p.y) > 1.) return 0.;
  float c = floor(p.x * n), f = fract(p.x * n) - .5, r = h1(c + sd * 7.);
  float s = ln(f + (r - .5) * .3 * p.y, .09) * step(abs(p.y), .5 + .5 * h1(c + sd));
  s += ln(p.y - (r - .5), .12) * step(abs(f), .32) * step(.4, h1(c + 3. + sd));
  s += ln(length(vec2(f, p.y * .6 - (r - .5) * .5)) - .22, .08) * step(.6, h1(c + 5. + sd));
  return sat(s) * step(.12, h1(c + 9. + sd));
}
// a bramble growing up from q = 0 to height h, with thorns
void vine(inout vec3 col, vec2 q, float h, float sd, vec3 ca, vec3 cb){
  if (h < .04 || q.y < -.02 || q.y > h || abs(q.x) > .6) return;
  float u = q.y / h, x = q.x - sin(q.y * 4. + sd * 5.) * .13 * u - (h1(sd) - .5) * .5 * u, w = .075 * (1. - u * .85);
