float in_area(vec2 c){
  if (uShape == 1) return step(abs(c.x) + abs(c.y), uSize + .01);
  if (uShape == 2) return step(min(abs(c.x), abs(c.y)), .01) * step(max(abs(c.x), abs(c.y)), uSize + .01);
  if (uShape == 6) return 1.;
