float spot_on(int i){ if (aresGame) return i < aresSpotCount ? 1. : 0.; return (uShape == 3 || uShape == 7) ? step(float(i), uSize - .5) : (uShape == 1 || uShape == 2) ? 1. : (i == 0 ? 1. : 0.); }

void ground(inout vec3 col, vec2 g){
  vec2 c = floor(g + .5), fc = aresGame ? fract(aresBoardPoint(g)) - .5 : g - c;
  float inb = aresGame ? aresCell(g).r : step(abs(c.x), 7.) * step(abs(c.y), 3.);
  vec3 gc = mix(vec3(.085, .075, .13), vec3(.115, .1, .17), mod(c.x + c.y, 2.));
