  col += uC2 * (1. - smoothstep(0., 1.3, length(d))) * .2 * sat(uS * 2.) * k;
  if (uTr > 0.) col += uC1 * ln(length(d) - (1.3 + 2.6 * eo(uTr / .5)), .12) * (1. - sat(uTr / .5)) * inb;
