  // the cells the spell will hit, then the hit itself spreading cell by cell
  vec2 rc = aresGame ? floor(aresBoardPoint(g)) - floor(aresBoardPoint(uTgt.xz)) : c - floor(uTgt.xz + .5); d = g - uTgt.xz;
  float area = (aresGame ? aresCell(g).g : in_area(rc)) * inb, dist = (uShape == 3 || uShape == 7) ? rc.x : abs(rc.x) + abs(rc.y), ti = uI;
  float r = length(d), a = atan(d.y, d.x);
  if (area > 0. && uTr > 0.) {
    float show = sat(uTr * (uSize + 3.) - dist) * (ti < 0. ? 1. : 1. - sat(ti * 3.)) * (uSet < 0. ? 1. : 1. - sat(uSet * 2.5));
    float mark = ln(edge - .4, .035) * (.6 + .4 * sin(uT * 8. - dist)) + ln(abs(fc.x) + abs(fc.y) - .14 - .04 * sin(uT * 6.), .03) + .1;
    col += (uC2 + uC1 * .3) * mark * show;
  }
  if (uClass == 2 && uStart == 1 && uS > 0.) { vec2 sd = g - uCst.xz - vec2(.28, 0.); float sr = length(sd); col += (uC2 + uC1 * .4) * smoothstep(.75, 1., sin(atan(sd.y, sd.x) * 7. + fbm(vec2(sr * 2., uT)) * 2.5)) * (1. - smoothstep(0., 2.2 * uS, sr)) * k * inb; }
  if (uClass == 1 && uCrawl > .5 && uTr > 0. && uTr < 1.) {       // a shadow running along the ground
    vec2 hA = uCst.xz, ab = mix(uCst.xz, uTgt.xz, uTr) - hA; float L = max(length(ab), .01);
    vec2 pa = g - hA; float h = clamp(dot(pa, ab) / (L * L), 0., 1.);
    float wd = (.1 + .34 * h) * (.6 + .8 * fbm(g * 3. + uT * 2.)) * smoothstep(0., .25, h - max(uTr - .55, 0.) * 2.);
    shade(col, 1. - length(pa - ab * h) / max(wd, .01));
  }
  if (uTrap > .5 && uSet >= 0. && area > 0.) {     // the trap: shown as it is set, then hidden
    float vis = ti < 0. ? mix(1., .14, smoothstep(.5, 1.1, uSet)) : 1. - sat(ti * 4.);
    float teeth = emblem(fc / .46, uSeed + floor(h2(c) * 9.), 1.) * .8;
    col = mix(col, vec3(.02, 0., .05), (1. - smoothstep(.36, .5, length(fc) * (.9 + .25 * fbm(g * 4. + uT)))) * .8 * vis);
    col += (uC2 + uC1 * .3) * teeth * vis * (1. + 2. * exp(-uSet * 5.));
  }
  if (uClass == 11 && uCrawl > .5 && uTr > 0. && length(uTgt - uFrom) > .5) {     // the Mori: roots run under the ground to the target
    vec2 A = uFrom.xz, ab = uTgt.xz - A; float L = length(ab); vec2 n = ab / L;
    float x = dot(g - A, n), y = dot(g - A, vec2(-n.y, n.x)), kk = L * sat(uTr), fade = uI < 0. ? 1. : 1. - sat(uI / 1.4);
    for (int i = 0; i < 3; i++) {
