    for (int i = 0; i < 3; i++) { float p = fract(ti * .35 + float(i) / 3.); col += uX1 * ln(abs(d.x) + abs(d.y) - p * (uSize + .5), .07) * (1. - p) * win(ti, .1, 9., .3); }
