void main(){
  uv = (gl_FragCoord.xy - .5 * uRes) / uRes.y;
  ro = uCam; fw = normalize(uLook - ro); rt = normalize(cross(fw, vec3(0., 1., 0.))); up = cross(rt, fw);
  if (aresGame) ro = aresOrigin();
  vec3 rd = aresRay();
  vec3 col = aresGame ? aresBackground() : mix(vec3(.03, .025, .055), vec3(.075, .05, .13), uv.y + .5);
  if (rd.y < -.001) { vec3 g = ro + rd * (-ro.y / rd.y); ground(col, g.xz); }

  vec3 n, nn; float t = 1e9, tt; vec3 bc = vec3(0.);
  float charge = sat(uS * 2.) * (1. - sat(uTr * 3.));
  if (uClass == 4) {                                // behind the Tokei: a great dial, or echoes of himself
    if (charge > 0. && uStart == 0) { float sp = uS * uS * 40.; col += GOLD * dial(bb(uCst + vec3(0., 1.05, 0.)) / 1.3, sp / 12., sp, uS * 1.5) * charge; }
    if (charge > 0. && uStart == 3) for (int j = 0; j < 3; j++) {
      float off = (float(j) - 1.) * (1. - eo(uS)); vec2 eq = bb(uCst + vec3(off * 1.5 + (j == 1 ? -1.2 * (1. - eo(uS)) : 0.), 0., off * .6));
      col += uC2 * step(abs(eq.x), .2 + .05 * fbm(eq * 6. + uT)) * step(0., eq.y) * step(eq.y, 1.4) * .32 * charge;
    }
    if (uCrawl > .5 && length(uFrom - uCst) > .5) for (int j = 0; j < 5; j++) {       // where he was a moment ago
      vec2 eq = bb(mix(uFrom, uCst, (float(j) + .3) / 5.));
      col += uC2 * step(abs(eq.x), .2 + .05 * fbm(eq * 6. + uT)) * step(0., eq.y) * step(eq.y, 1.4) * .38 * (uI < 0. ? 1. : 1. - sat(uI / .8)) * (float(j) + 1.) / 6.;
    }
  }
  if (uClass == 1 && charge > 0.) {
    vec2 cq = bb(uCst);
    if (uStart == 0) shade(col, fire_d(cq + vec2(0., .12), .55, 2.2 * charge, 9.));
