        float fj = float(j);
        slash(col, bb(T + vec3(0., .75, 0.)), (1.15 + .3 * fj) * uPow, fj < .5 ? 2.4 : fj < 1.5 ? -.6 : 1.2, fj < .5 ? -3.2 : fj < 1.5 ? 3. : -2.8, (ti - .09 * fj) / .34, uC1, uC2);
      }
      if (uEl == 2 && uShape == 1 && uSize < 1.5) slash(col, bb(T + vec3(0., .7, 0.)), 1.9, 0., TAU, ti / .5, uC1, uC2);
      for (int i = 0; i < 12; i++) { float fi = float(i), an = fi * 2.399, sp = (2. + 3. * h1(fi)) * uPow; col += uC1 * pt(T + vec3(cos(an) * sp * ti, .6 + (2. + 2. * h1(fi + 5.)) * ti - 5. * ti * ti, sin(an) * sp * ti), 34.) * (1. - sat(ti / .9)) * step(uEl < 4 ? 0. : 9., ti + (uEl < 4 ? 0. : 0.)); }
      if (uFrost > .5) {                             // he cuts himself: the price of the power
        slash(col, bb(uCst + vec3(0., .8, 0.)), .9, 2.2, -3., ti / .3, vec3(1., .5, .5), vec3(.9, .1, .12));
        for (int i = 0; i < 8; i++) { float fi = float(i), an = fi * .8; col += vec3(1., .15, .18) * pt(uCst + vec3(cos(an) * ti * 1.6, .9 + 1.5 * ti - 5. * ti * ti, sin(an) * ti), 30.) * (1. - sat(ti / .7)); }
      }
    }
    if (uEl == 0 && uClass != 2 && (uHeavy > .5 || uShape == 1)) paint(col, ball_d(bb(T + vec3(0., .7, 0.)), (1.2 + .5 * uSize) * eo(ti / .2), 1.) * (1. - smoothstep(.2, .6, ti)), uC1, uC2, uC3);
    if (uEl == 2 || uFx == 7) {          // wind blades: thick cartoon crescents
      vec3 ca = uFx == 7 ? uX2 : uC1, cb = uFx == 7 ? uX1 : uC2; float t0 = uFx == 7 ? .22 : .08;
      for (int j = 0; j < 3; j++) {
        float fj = float(j), tk = (ti - t0 - .11 * fj) / .28;
        if (tk < 0. || tk > 1.) continue;
        vec2 e = rot(bb(T + vec3(0., .7, 0.)), fj * 2.2 + 1. + tk * 1.4) / (1.15 * uPow);
        float r1 = length(e), r2 = length(e - vec2(.1, 0.));
        float cres = step(r1, 1.) * step(.96, r2) * step(-.2, e.x - 1. + tk * 2.4) * step(e.x - 1. + tk * 2.4, .9);
        if (uClass == 1) { col = mix(col, vec3(.02, 0., .05), cres); col += uC2 * cres * (1. - smoothstep(.0, .05, r2 - .96)) + uC1 * cres * smoothstep(.96, 1., r1); }
        else col = mix(col, mix(cb, ca, smoothstep(.97, 1.03, r2)), cres);
      }
    }

    // ----- what the spell does besides damage -----
    if (uFx == 1 && uPushK > 0. && uPushK < 1.) {
      vec2 e = bb(uDum + vec3(0., .7, 0.));
      for (int j = 0; j < 5; j++) { float y = (float(j) - 2.) * .22; col += uC1 * ln(e.y - y, .02) * step(-1.6 - .5 * h1(float(j)), e.x) * step(e.x, -.3) * (1. - uPushK); }
      paint(col, ball_d(bb(uDum + vec3(-.45, .1, 0.)), .3, 3.) * (1. - uPushK), vec3(.8, .78, .85), vec3(.5, .47, .58), vec3(.3, .27, .36));
    }
    if (uFx == 2 || uFx == 3 || uFx == 8) {
      vec3 A0 = uDum + vec3(0., .8, 0.), B0 = uCst + vec3(0., .9, 0.);
      for (int j = 0; j < 5; j++) {
        float fj = float(j), p = (ti - .4 - .1 * fj) / .75;
        if (p < 0. || p > 1.) continue;
        float pe = p * p * (3. - 2. * p);
        for (int s = 0; s < 3; s++) {
          float ps = max(pe - float(s) * .05, 0.);
          vec3 P = mix(A0, B0, ps) + vec3(0., sin(PI * ps) * (1.4 + .3 * fj), sin(PI * ps) * (fj - 2.) * .7);
          if (s == 0) {
            vec2 e = rot(bb(P), uFx == 3 ? .785 + uT * 3. : 0.);
            float body = uFx == 3 ? step(max(abs(e.x), abs(e.y)), .1) : step(length(e), .11);
            col = mix(col, uX1, body); col = mix(col, uX2, uFx == 3 ? step(max(abs(e.x), abs(e.y)), .05) : step(length(e - vec2(-.03, .03)), .05));
            col += uX1 * exp(-length(e) * 7.) * .7;
          } else col += uX1 * pt(P, 26.) * (1. - float(s) * .3);
        }
      }
      float arrive = (ti - 1.1) / .9;
      if (arrive > 0. && arrive < 1.) { col += uX1 * ln(length(bb(B0)) - 1.1 * eo(arrive), .07) * (1. - arrive); chevrons(col, uCst + vec3(0., .9, 0.), 1., uX2, 1. - arrive); }
    }
    if (uFx == 4 || uFx == 3 || uFx == 8) {      // rune shackles and falling arrows on the target
      for (int i = 0; i < 2; i++) {
        float fi = float(i);
        vec2 e2 = bb(T + vec3(0., .4 + .75 * fi, 0.)); e2.y *= 2.7;
        float r2 = length(e2), an = atan(e2.y, e2.x) + uT * (fi < .5 ? 1.6 : -1.6);
        float close = mix(1.9, .78, pop((ti - .3 - .12 * fi) / .35));
        col += (uX1 + uX2 * .4) * (ln(r2 - close, .035) + glyphs(an, r2, close - .1, .07, 14., fi + 2.)) * win(ti, .3 + .12 * fi, 3.4, .6);
      }
      chevrons(col, T + vec3(0., 1.5, 0.), -1., uX1 + uX2 * .3, win(ti, .3, 3.4, .6));
    }
    if (uFx == 5) {
      for (int j = 0; j < 7; j++) {
        float fj = float(j), p = fract(h1(fj) + ti * (.35 + .2 * h1(fj + 1.)));
        vec2 e = bb(T + vec3((h1(fj + 2.) - .5) * 1.1, p * 2., (h1(fj + 6.) - .5) * .7));
        float R = (.08 + .1 * h1(fj + 4.)) * (.4 + p), rr = length(e);
        float w = win(ti, .15, 4.2, .8) * step(p, .9);
        col = mix(col, uX1, step(rr, R) * w * .85); col = mix(col, uX1 * .4, ln(rr - R, .025) * w);
        col = mix(col, uX2, step(length(e - vec2(-.3, .3) * R), R * .28) * w);
      }
      chevrons(col, T + vec3(0., 1.5, 0.), -1., uX1, win(ti, .4, 4.2, .8));
    }
    if (uFx == 8) for (int j = 0; j < 8; j++) {  // bats
      float fj = float(j), an = fj * .785 + ti * (1.6 + .3 * h1(fj)), rad = (1.2 + 1.6 * h1(fj + 1.)) * eo(ti / .5);
      vec2 e = bb(T + vec3(cos(an) * rad, 1. + .5 * sin(ti * 3. + fj), sin(an) * rad * .8));
      float flap = .5 + .45 * sin(uT * 22. + fj), wing = step(abs(e.x), .2) * step(abs(e.y - abs(e.x) * flap + .02), .05 + .04 * (1. - abs(e.x) * 5.));
      float w = win(ti, .1, 3.8, .7);
      col = mix(col, vec3(.07, .03, .13), max(wing, step(length(e), .05)) * w);
      col += uX1 * step(length(vec2(abs(e.x) - .018, e.y - .012)), .008) * w * 2.;
    }
    if (uFx == 9) {                                // vanishing: a puff of shadow, then only an outline is left
      vec3 W = uGhostD > 0. ? uDum : uCst;
      shade(col, ball_d(bb(W + vec3(0., .7 + ti * .9, 0.)), .75, 2.) * (1. - smoothstep(.1, .7, ti)) - .22);
      col += uC2 * ln(length(bb(W + vec3(0., .7, 0.))) - 1.3 * eo(ti / .4), .05) * (1. - sat(ti / .5));
      for (int j = 0; j < 8; j++) { float fj = float(j), p = fract(h1(fj) + ti * .5); col += uC1 * pt(W + vec3((h1(fj + 2.) - .5) * .9, p * 2.2, (h1(fj + 5.) - .5) * .6), 40.) * sin(PI * p) * win(ti, .1, 4.2, .6); }
    }
    if (uFx == 6) {
      vec3 B0 = uCst; float w = win(ti, .15, 9., .3);
      chevrons(col, B0 + vec3(0., .3, 0.), 1., uX1, w);
      chevrons(col, B0 + vec3(.5, .1, .3), 1., uX2, w * .7);
      vec2 e = bb(B0 + vec3(0., .75, 0.));
      if (uStat == 0) {                 // reticle locks on
        float R = mix(2.2, .62, pop((ti - .2) / .4)), rr = length(e), an = atan(e.y, e.x) + ti * 3. * (1. - eo((ti - .2) / .6));
        float tick = step(abs(fract(an * 4. / TAU + .5) - .5), .06) * step(abs(rr - R), .16);
        col += (uX1 * (ln(rr - R, .035) + tick) + uX2 * (ln(e.x, .012) + ln(e.y, .012)) * step(rr, R * .5) * step(R, .7)) * w;
        col += uX2 * (exp(-abs(e.y) * 40.) * exp(-abs(e.x) * 2.) + exp(-abs(e.x) * 40.) * exp(-abs(e.y) * 2.)) * exp(-sq((ti - .6) * 7.)) * 1.5;
      } else if (uStat == 1 && uClass == 1) {   // the Yajin: an aura of shadow breathing around the body, with wisps climbing off it
        float grow = pop((ti - .1) / .35) * (1. - smoothstep(3., 3.8, ti)) * step(.1, ti);
        vec2 a2 = bb(B0 + vec3(0., .85, 0.)); float ar = length(vec2(a2.x / .62, a2.y / 1.25)), aa = atan(a2.y, a2.x);
        float n1 = fbm(vec2(aa * 2.2 + uT * .5, ar * 2. - uT * 1.6)), n2 = fbm(vec2(a2.x * 5., a2.y * 3.5 - uT * 2.8));
        float upk = sat(a2.y / 2.5 + .5), edge = 1.12 + (.2 + .75 * upk) * (n2 - .35) + .12 * (n1 - .5) + .05 * sin(uT * 2.4);
        float d1 = min(edge - ar, (ar - .66 - .12 * n1) * 1.5);                 // hollow: the body stays visible inside
        shade(col, d1 * .9 * grow);
        col += uC2 * exp(-abs(ar - .95) * 3.) * .14 * grow * (.6 + .4 * sin(uT * 2.4));
        for (int j = 0; j < 7; j++) {                                            // thin wisps tearing off upward
          float fj = float(j), p = fract(ti * (.4 + .25 * h1(fj)) + h1(fj + 3.)), an = fj * 2.399;
          vec2 w2 = bb(B0 + vec3(cos(an) * (.6 - .3 * p), .9 + p * 2.2, sin(an) * .4)); w2.x += sin(w2.y * 9. + fj + uT * 3.) * .05; 
          float wd = 1. - length(vec2(w2.x / (.07 * (1. - p) + .01), w2.y / .32));
          shade(col, wd * (.35 + .5 * fbm(w2 * 12. + uT * 2.)) * grow * sin(PI * p));
        }
      } else if (uStat == 1 && uClass == 2) {   // the Senshi: a battle aura hugging the body, with light streaming up off it
        float grow = pop((ti - .1) / .3) * (1. - smoothstep(3., 3.8, ti)) * step(.1, ti);
        vec2 a2 = bb(B0 + vec3(0., .85, 0.)); float ar = length(vec2(a2.x / .66, a2.y / 1.3)), aa = atan(a2.y, a2.x);
        float n1 = fbm(vec2(aa * 2.2 + uT * .5, ar * 2. - uT * 1.6)), n2 = fbm(vec2(a2.x * 5., a2.y * 3. - uT * 4.));
        float upk = sat(a2.y / 2.6 + .5), edge = 1.1 + (.15 + .9 * upk) * (n2 - .35) + .1 * (n1 - .5) + .06 * sin(uT * 5.);
        float d1 = min(edge - ar, (ar - .7 - .1 * n1) * 1.6);
        float au = max(d1, 0.) * grow;                                           // soft light, not flame: a glow with a bright skin
        col += uC2 * smoothstep(0., .3, au) * .5 + uC1 * smoothstep(.12, .45, au) * .45 + uX1 * smoothstep(.0, .12, au) * (1. - smoothstep(.12, .3, au)) * .5;
        col += uC1 * ln(d1, .035) * grow * .9;
        col += uX1 * exp(-abs(ar - .95) * 2.6) * .22 * grow * (.7 + .3 * sin(uT * 5.));
        for (int j = 0; j < 8; j++) {                                            // streaks of light rising off him
          float fj = float(j), p = fract(ti * (.7 + .4 * h1(fj)) + h1(fj + 3.)), an = fj * 2.399;
          vec2 w2 = bb(B0 + vec3(cos(an) * .62, .2 + p * 2.9, sin(an) * .4));
          col += mix(uX2, uX1, p) * exp(-abs(w2.x) * 60.) * exp(-abs(w2.y) * 5.) * sin(PI * p) * grow * 1.3;
        }
        vec2 g2 = bb(B0 + vec3(0., .05, 0.)); g2.y *= 2.7; col += uX2 * ln(length(g2) - 1.2 * fract(ti * 1.2), .05) * (1. - fract(ti * 1.2)) * grow;
      } else if (uStat == 1) {          // flame aura
        float hh = 2.6 * pop((ti - .15) / .3) * (1. - .45 * smoothstep(.6, 1.4, ti)) * step(.15, ti);
        float dn = fire_d(bb(B0) + vec2(0., .1), .75, hh, 5.);
        paint(col, dn * (1. - smoothstep(.0, .5, dn) * smoothstep(.9, 1.5, ti) * .0), uX2, uX1, uX1 * .45);
      } else if (uStat == 2) {          // arrows in orbit
        for (int j = 0; j < 5; j++) {
          float an = float(j) * 1.257 + ti * 2.2;
          vec2 a = bb(B0 + vec3(cos(an) * .9, .75 + .25 * sin(ti * 2. + float(j)), sin(an) * .9));
          float sh = step(abs(a.x), .018) * step(abs(a.y), .3) + step(abs(a.x) + (a.y - .3) * .8, .1) * step(.2, a.y) * step(a.y, .42);
          if (uClass == 2) ssword(col, vec2(a.x, .5 - a.y) , .9 * w * eo((ti - .15) / .3), 0., uX2, uX1);
          else col = mix(col, mix(uX1, uX2, .5 + .5 * sin(an)), min(sh, 1.) * w * eo((ti - .15) / .3));
        }
      } else if (uStat == 4) {          // healing: soft rings rise through him
        for (int j = 0; j < 3; j++) { float p = fract(ti * .5 + float(j) / 3.); vec2 r2 = bb(B0 + vec3(0., p * 1.9, 0.)); r2.y *= 2.7; col += (uX1 + uX2 * .5) * ln(length(r2) - .75 + .25 * p, .04) * sin(PI * p) * w; }
        col += uX1 * exp(-length(e) * 1.6) * .5 * exp(-ti * 1.2);
      } else {                          // an eye opens above
        vec2 o = bb(B0 + vec3(0., 2.1, 0.)); float open = pop((ti - .2) / .4) * .34, lid = open * (1. - sq(o.x / .6));
        if (abs(o.x) < .6) col += (uX1 * ln(abs(o.y) - lid, .035) + uX2 * step(length(o), min(.13, lid)) + uX1 * ln(length(o) - .2, .03) * step(abs(o.y), lid)) * w * 1.4;
      }
    }

    if (uHeavy > .5) {
      float l = dot(col, vec3(.4));
      col = mix(col, mix(uC1, vec3(.02, .01, .05), smoothstep(.12, .4, l)), step(.05, ti) * step(ti, .11));
      col = mix(col, uC1 * .7 + .5, step(ti, .05) * .9);
    } else col += uC1 * (1. - sat(ti / .07)) * .3 * uPow;
  }

  col = col / (1. + col * .22);
  col *= 1. - .35 * dot(uv, uv);
  gl_FragColor = vec4(pow(max(col, 0.), vec3(.9)), 1.);
  if (aresGame && aresComposite) gl_FragColor = aresOverlay(gl_FragColor.rgb);
}
